// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EnterpriseResource) predicate.EnterpriseResource {
	return predicate.EnterpriseResource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EnterpriseResource) predicate.EnterpriseResource {
	return predicate.EnterpriseResource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EnterpriseResource) predicate.EnterpriseResource {
	return predicate.EnterpriseResource(sql.NotPredicates(p))
}
